mapper.select:
SELECT id, business_type AS businessType, CASE business_type WHEN 'PAPER_SUBMIT' THEN '论文审稿通知' WHEN 'PAPER_PASS' THEN '论文审核通过' WHEN 'PAPER_REJECT' THEN '论文审核拒绝' WHEN 'USER_REGISTER' THEN '注册成功通知' WHEN 'RESET_PASSWORD' THEN '密码重置' WHEN 'MEETING_NOTICE' THEN '会议提醒' WHEN 'ADMIN_ERROR_NOTIFY' THEN '管理员错误通知' ELSE business_type END AS businessTypeDesc, business_id AS businessId, receiver, receiver_name AS receiverName, subject, send_status AS sendStatus, CASE send_status WHEN 0 THEN '待发送' WHEN 1 THEN '已提交至邮件服务器' WHEN 2 THEN '发送失败' WHEN 3 THEN '重试中' WHEN 4 THEN '已取消' WHEN 5 THEN '退信-投递失败' WHEN 6 THEN '待重试' WHEN 7 THEN '重试成功' WHEN 8 THEN '重试失败' ELSE CONCAT('未知状态(', send_status, ')') END AS sendStatusDesc, delivery_status AS deliveryStatus, CASE delivery_status WHEN 0 THEN '等待投递' WHEN 1 THEN '已投递' WHEN 2 THEN '已退信' WHEN 3 THEN '投递中' ELSE CONCAT('未知状态(', IFNULL(delivery_status, -1), ')') END AS deliveryStatusDesc, retry_count AS retryCount, error_message AS errorMessage, bounce_reason AS bounceReason, bounce_code AS bounceCode, parent_record_id AS parentRecordId, record_type AS recordType, retry_sequence AS retrySequence, root_record_id AS rootRecordId, message_id AS messageId, consume_time AS consumeTime, sender, send_time AS sendTime, create_time AS createTime FROM mail_send_record
(record_type = 'ORIGINAL' OR record_type IS NULL OR parent_record_id IS NULL)
AND business_type = #{query.businessType}
AND business_id = #{query.businessId}
AND receiver LIKE CONCAT('%', #{query.receiver}, '%')
AND send_status = #{query.sendStatus}
AND delivery_status = #{query.deliveryStatus}
AND subject LIKE CONCAT('%', #{query.subject}, '%')
AND create_time >= #{query.startTime}
AND create_time <= #{query.endTime}
ORDER BY create_time DESC

SELECT id, business_type AS businessType, CASE business_type WHEN 'PAPER_SUBMIT' THEN '论文审稿通知' WHEN 'PAPER_PASS' THEN '论文审核通过' WHEN 'PAPER_REJECT' THEN '论文审核拒绝' WHEN 'USER_REGISTER' THEN '注册成功通知' WHEN 'RESET_PASSWORD' THEN '密码重置' WHEN 'MEETING_NOTICE' THEN '会议提醒' WHEN 'ADMIN_ERROR_NOTIFY' THEN '管理员错误通知' ELSE business_type END AS businessTypeDesc, business_id AS businessId, receiver, receiver_name AS receiverName, subject, send_status AS sendStatus, CASE send_status WHEN 0 THEN '待发送' WHEN 1 THEN '已提交至邮件服务器' WHEN 2 THEN '发送失败' WHEN 3 THEN '重试中' WHEN 4 THEN '已取消' WHEN 5 THEN '退信-投递失败' WHEN 6 THEN '待重试' WHEN 7 THEN '重试成功' WHEN 8 THEN '重试失败' ELSE CONCAT('未知状态(', send_status, ')') END AS sendStatusDesc, delivery_status AS deliveryStatus, CASE delivery_status WHEN 0 THEN '等待投递' WHEN 1 THEN '已投递' WHEN 2 THEN '已退信' WHEN 3 THEN '投递中' ELSE CONCAT('未知状态(', IFNULL(delivery_status, -1), ')') END AS deliveryStatusDesc, retry_count AS retryCount, error_message AS errorMessage, bounce_reason AS bounceReason, bounce_code AS bounceCode, parent_record_id AS parentRecordId, record_type AS recordType, retry_sequence AS retrySequence, root_record_id AS rootRecordId, message_id AS messageId, consume_time AS consumeTime, sender, send_time AS sendTime, create_time AS createTime FROM mail_send_record WHERE record_type = 'RETRY' AND root_record_id IN
#{rootId}
ORDER BY root_record_id, retry_sequence ASC
